planForecast=reserveForecast;
planFunding=function(p=currentPlan()){let f=reserveForecast(p),free=f.start.available,map={};for(let x of p.items.filter(x=>x.enabled).sort((a,b)=>a.day-b.day)){if(x.kind==='card'){let bill=plannerStore.cardBills.find(b=>b.id===x.statementId),key=bill?reserveCycleKey(bill.card,bill.statementMonth):'manual:'+x.id,held=p.reserveModel.openingBuckets[key]?.amount||0;map[x.id]=held>=x.amount?'Funded by opening earmark':held>0?'Partly earmarked':'Fund from bank cash when due';continue}if(reserveIsCard(x,p)){let e=f.events.filter(e=>e.itemId===x.id),gap=e.some(e=>e.unfunded>0);map[x.id]=gap?'Reservation funding shortfall':'Projected card earmark';continue}if(['income','funding','withdrawal','reimbursement','transfer'].includes(x.kind))continue;map[x.id]=free>=x.amount?'Funded now':free>0?'Partly funded now':'Needs future receipts';free-=x.amount}return map};
plannerMetrics=function(p=currentPlan()){let m=planTotals(p),f=reserveForecast(p);return `<div class="reserve-view-label"><span>INCOME & SPENDING</span><span>Charges count when incurred. Payments settle the liability.</span></div><div class="plan-metrics reserve-metrics">${[['Expected earned income',m.income,'Other receipts '+money(m.receipts-m.income),'receipts'],['Planned consumption',m.spend,money(m.cardSpend)+' on cards · '+money(m.bankSpend)+' directly paid','spending'],['Surplus before investments',m.surplus,'Income − consumption · net investment '+money(m.invested),'surplus']].map(([n,v,desc,k])=>`<button class="plan-metric" data-reserve-explain="${k}"><small>${n}</small><strong class="num">${money(v)}</strong><em>${desc}</em></button>`).join('')}</div><div class="reserve-view-label"><span>BANK CASH & EARMARKS</span><span>${p.partial?'Partial balance coverage · ':' '}Reservations stay inside bank cash.</span></div><div class="plan-metrics reserve-metrics">${[['Projected bank balance',f.closing.bank,money(m.bankPayments)+' bank payments · net cash flow '+money(m.bankCashflow),'bank'],['Reserved for card payments',f.closing.reserved,'Projected month end · '+money(f.start.reserved)+' opening card earmarks','reserves'],['Available after all earmarks',f.closing.available,f.shortfall?'Card payment funding shortfall '+money(f.shortfall):'Bank cash − card earmarks − other reserves','available']].map(([n,v,desc,k])=>`<button class="plan-metric ${k==='available'?(f.shortfall||v<0?'warn':'highlight'):''}" data-reserve-explain="${k}"><small>${n}</small><strong class="num">${money(v)}</strong><em>${desc}</em></button>`).join('')}</div>`};
function reservePanel(){let p=currentPlan(),f=reserveForecast(p),charges=p.items.filter(x=>x.enabled&&reserveIsCard(x,p)),rules=reservePolicies(),short=f.shortfall||f.cashShortfall||f.otherShortfall;return `<section class="panel reserve-panel"><div class="section-label"><div><h2>Your money is still in the bank. It just has a job.</h2><p>Card charges create consumption and an earmark. Bill payments use the earmark.</p></div><button class="button" data-reserve-action="cycles">Billing cycles ↗</button></div><div class="reserve-equation"><span><small>Bank cash · month end</small><b>${money(f.closing.bank)}</b></span><i>−</i><span><small>Card earmarks</small><b>${money(f.closing.reserved)}</b></span><i>−</i><span><small>Other earmarks</small><b>${money(f.closing.other)}</b></span><i>=</i><span class="reserve-answer"><small>Unreserved, available</small><b>${money(f.closing.available)}</b></span></div>${p.reserveModel.carryFrom&&plannerStore.plans[p.reserveModel.carryFrom.key]?.revision!==p.reserveModel.carryFrom.revision?'<div class="info-strip">Previous plan has changed since this opening snapshot. Review Opening bank balances and refresh the projected carry-forward.</div>':''}${short>0?`<div class="reserve-alert"><b>◉ ${f.shortfall?'Card payment funding shortfall':f.cashShortfall?'Funding account shortfall':'Cash earmark funding shortfall'} · ${money(short)}</b><p>${f.shortfall?'The required card reserve is larger than the known cash available to fund it. Unfunded amounts are never labeled reserved.':'A scheduled payment or earmark exceeds its funding account’s available cash. Review timing and starting funds.'}</p></div>`:''}<div class="reserve-table-wrap"><table class="ledger reserve-charge-table"><thead><tr><th>This month’s card charge</th><th>Consumption</th><th>Bank payment now</th><th>Expected bill payment</th><th>Reservation funding</th></tr></thead><tbody>${charges.map(x=>{let c=reserveChargeParts(x,p)[0]?.cycle,e=f.events.filter(e=>e.itemId===x.id),funded=sum(e,z=>Math.max(0,z.reserveDelta));return `<tr><td><button data-plan-edit="${x.id}"><b>${esc(x.title)}</b><small>${esc(x.account)} · ${x.day} ${plannerMonth(state.month)}</small></button></td><td>${money(x.amount)}</td><td>${money(0)}</td><td>${c?dateLabel(c.dueDate)+' '+c.dueDate.slice(0,4):'Cycle needed'}<small>Estimated · ${esc(c?.bank||'Unassigned bank')}</small></td><td>${e.some(z=>z.unfunded>0)?'<span class="tag amber">Shortfall at charge date</span>':'<span class="tag">Projected earmark</span>'}<small>Cash remains in your bank</small></td></tr>`}).join('')||'<tr><td colspan="5">No enabled card-funded expenses. Choose a credit card as the payment account when editing an expense.</td></tr>'}</tbody></table></div><div class="reserve-panel-actions"><button class="button" data-reserve-action="fund">Manage opening card earmarks</button><button class="button" data-reserve-action="payment-preview">See payment & release →</button><button class="tiny-button" data-reserve-action="opening">Opening bank balances ↗</button></div><p class="plan-help" style="margin-top:12px">Opening earmarks are local planning allocations, not a bank lock. Future earmarks and bill totals are projections until charges and statements are confirmed. Cycle settings are editable fictional demo assumptions.</p></section>`}
const reserveLaneBefore=plannerLane;plannerLane=function(k){let html=reserveLaneBefore(k),p=currentPlan();for(let x of p.items.filter(x=>x.lane===k&&reserveIsCard(x,p)))html=html.replace('<b>'+esc(x.title)+'</b>','<b>'+esc(x.title)+'</b><span class="tag blue">Credit card · consumption now, payment later</span>');return html};
plannerCanvas=function(){let p=currentPlan(),m=planTotals(p),f=reserveForecast(p);return reservePanel()+cardBillPanel()+`<div class="plan-grid"><div><div class="plan-section-head"><div><h3>This month’s life, thoughtfully arranged</h3><p>Expenses stay in their categories, whichever account pays.</p></div>${planStatus(p)}</div>${Object.keys(planLanes).map(plannerLane).join('')}<div class="plan-footer"><p>Plans and reservations do not post actual transactions.<br>Every card payment is separate from consumption.</p><div class="plan-top-actions"><button class="button" data-plan-action="history">Revision history</button>${p.status==='draft'?'<button class="button primary" data-plan-action="activate">Review & activate →</button>':p.status==='active'?'<button class="button primary" data-plan-action="linked-budget">Open linked budget ↗</button><button class="button" data-plan-action="close-plan">Close month ✓</button>':'<button class="button" data-plan-action="reopen">Reopen as draft</button>'}</div></div></div><aside class="plan-aside"><section class="panel">${sectionHead('This month’s bank payments','Cash leaving bank accounts, not a second spending total')}${[['Direct consumption',m.bankSpend],['Card bills due',m.card],['Investment contributions',m.contributions]].map(([n,v])=>`<div class="allocation-line"><span>${n}</span><b>${money(v)}</b></div>`).join('')}<button class="view-all" data-plan-tab="calendar">Open cash calendar ↗</button></section><section class="panel">${sectionHead('Card earmarks: the bridge','Opening → new funding → payment release')}<div class="allocation-line"><span>Opening card reserve</span><b>${money(f.start.reserved)}</b></div><div class="allocation-line"><span>Released when bills are paid</span><b>${money(sum(f.events,e=>e.released||0))}</b></div><div class="allocation-line"><span>Closing funded reserve</span><b>${money(f.closing.reserved)}</b></div><div class="allocation-line"><span>Closing reserve shortfall</span><b>${money(f.shortfall)}</b></div><button class="view-all" data-reserve-action="payment-preview">See why payment does not charge twice ↗</button></section><div class="plan-callout"><h3>◷ Protect the timing</h3><p>Lowest projected available cash ${money(f.low.balance)}${f.low.day?' on '+f.low.day+' '+plannerMonth(state.month):' at opening'}. ${f.below} days below your cash floor. ${p.partial?'Unknown balances are excluded.':''}</p><button class="button" data-plan-tab="scenarios">Stress-test this month ✧</button></div></aside></div>`};
plannerCalendar=function(){let p=currentPlan(),f=reserveForecast(p);return `<section class="panel"><div class="section-label"><div><h2>One calendar. Three connected balances.</h2><p>Bank cash, funded card earmarks, and unreserved available cash.</p></div><button class="button" data-reserve-action="opening">Edit opening</button></div>${plannerCashSVG(f,p)}<div class="table-scroll"><table class="ledger reserve-calendar"><thead><tr><th>Day / movements</th><th class="right">Bank cash</th><th class="right">Card earmarks</th><th class="right">Other reserves</th><th class="right">Available</th></tr></thead><tbody><tr><td>Opening position</td><td class="right">${money(f.start.bank)}</td><td class="right">${money(f.start.reserved)}</td><td class="right">${money(f.start.other)}</td><td class="right">${money(f.start.available)}</td></tr>${f.rows.map(r=>`<tr><td><button data-reserve-day="${r.day}"><b>${r.day} ${plannerMonth(state.month)}</b><small>${r.events.length?r.events.slice(0,2).map(e=>esc(e.title)).join(' · '):'No scheduled movement'}${r.events.length>2?' · +'+(r.events.length-2)+' more':''}</small></button></td><td class="right">${money(r.bank)}</td><td class="right">${money(r.reserved)}</td><td class="right">${money(r.other)}</td><td class="right ${r.balance<p.cashFloor?'danger':''}">${money(r.balance)}${r.shortfall?'<small>Reserve shortfall '+money(r.shortfall)+'</small>':''}</td></tr>`).join('')}</tbody></table></div><div class="info-strip">A new card charge changes consumption and funded earmarks, not bank cash. A bill payment reduces bank cash and releases its matching reserve. Daily available cash changes only by the unreserved portion of a payment. Unknown funding accounts and within-day clearance can still affect coverage.</div></section>`};
function reserveDay(day){let p=currentPlan(),f=reserveForecast(p),r=f.rows.find(r=>r.day===+day);openDrawer('Cash, earmarks & available · '+r.day+' '+plannerMonth(state.month),scopeName()+' · '+state.currency,`<div class="reserve-equation"><span><small>Bank cash</small><b>${money(r.bank)}</b></span><span><small>Card earmarks</small><b>${money(r.reserved)}</b></span><span><small>Available</small><b>${money(r.balance)}</b></span></div>${r.events.map(e=>`<div class="drawer-card"><h3>${esc(e.title)}</h3><p>${e.type==='charge'?'Card charge: consumption now, cash earmarked for a later bill.':e.type==='cardPayment'?'Card payment: liability settlement, not new consumption.':e.type==='otherReserve'?'Earmark: money remains in bank.':'Scheduled bank movement.'}<br>Bank cash change ${money(e.bankDelta)} · Card reserve change ${money(e.reserveDelta)}<br>Matching reserve released ${money(e.released||0)} · Available cash change ${money(e.amount)}</p>${e.unfunded?`<div class="info-strip">Funding shortfall ${money(e.unfunded)} at this event.</div>`:''}</div>`).join('')||'<div class="empty">No scheduled movements.</div>'}`)}
let reserveFundingRows=[];
function reserveTargets(p=currentPlan()){let targets=new Map();for(let b of billsForPlan(p)){targets.set(reserveCycleKey(b.card,b.statementMonth),{key:reserveCycleKey(b.card,b.statementMonth),card:b.card,statementMonth:b.statementMonth,required:billRemaining(b),bank:b.account,label:'Statement due '+dateLabel(b.dueDate)})}for(let x of p.items.filter(x=>x.enabled&&reserveIsCard(x,p)))for(let part of reserveChargeParts(x,p)){let c=part.cycle;if(!targets.has(c.key))targets.set(c.key,{...c,required:0,label:'Planned charges · payment '+dateLabel(c.dueDate)});let t=targets.get(c.key);t.planned=(t.planned||0)+part.amount;t.required=Math.max(t.required,t.planned)}for(let [key,b]of Object.entries(p.reserveModel.openingBuckets))if(!targets.has(key)&&b.required>0)targets.set(key,{...b,key,label:'Carried card obligation'});return [...targets.values()]}
function reserveFundingForm(){let p=currentPlan();if(p.status==='closed')return toast('Reopen this plan before changing its earmarks.');reserveFundingRows=reserveTargets(p);let banks=Object.entries(p.reserveModel.banks).filter(([,b])=>b.balance!==null);openDrawer('Give bank cash a job',monthName()+' · '+scopeName()+' · Opening planning position',`<div class="formula"><b>An earmark does not move money</b>Assign known bank cash to a card obligation. Bank balance stays unchanged; unreserved cash falls. When that bill is paid in the forecast, the matching reservation is released. These local plan allocations do not lock funds at your bank.</div><form id="reserve-funding-form">${reserveFundingRows.map((t,i)=>{let held=p.reserveModel.openingBuckets[t.key];return `<div class="drawer-card"><h3>${esc(t.card)} · ${monthName(t.statementMonth)}</h3><p>${esc(t.label)} · Required ${money(t.required)}</p><div class="form-grid"><div class="field"><label for="reserve-amount-${i}">Earmark now · ${state.currency}</label><input id="reserve-amount-${i}" name="amount-${i}" type="number" min="0" max="${t.required}" step=".01" value="${Math.min(held?.amount||0,t.required)}" required></div><div class="field"><label for="reserve-bank-${i}">Held in bank account</label><select id="reserve-bank-${i}" name="bank-${i}">${banks.map(([name])=>`<option ${name===(held?.bank||t.bank)?'selected':''}>${esc(name)}</option>`).join('')}</select></div></div></div>`}).join('')||'<div class="empty"><h3>No card obligations to fund yet</h3><p>Add a card-funded expense or a statement first.</p></div>'}<div class="info-strip">Funding is limited to known same-account cash after other opening reserves. Unknown balances cannot back a funded earmark. Existing carried reserves are included here rather than charged again.</div><div class="form-actions"><button type="button" class="button" data-reserve-action="autofund">Fill from available cash</button><button type="button" class="button" data-action="close">Cancel</button><button class="button primary" ${!banks.length?'disabled':''}>Save earmarks</button></div></form>`)}
openingForm=function(){let p=currentPlan(),model=p.reserveModel;if(p.status==='closed')return toast('Reopen this plan before changing its opening balances.');openDrawer('Start with bank cash, then earmark it',monthName()+' · '+scopeName(),`<div class="formula"><b>Keep cash and reservations separate</b>Enter gross bank balances before reserves. Blank balances remain Unknown. Card limits and expected income are not bank cash.<br>${esc(model.source)}</div><form id="reserve-opening-form">${Object.entries(model.banks).map(([name,b],i)=>`<div class="drawer-card"><h3>${esc(name)}</h3><div class="form-grid"><div class="field"><label for="reserve-opening-${i}">Bank balance · ${state.currency}</label><input name="balance-${i}" id="reserve-opening-${i}" type="number" step=".01" min="0" value="${b.balance===null?'':b.balance}" placeholder="Unknown"></div><div class="field"><label for="reserve-other-${i}">Other existing earmarks · ${state.currency}</label><input name="other-${i}" id="reserve-other-${i}" type="number" min="0" step=".01" value="${b.other||0}" required></div></div></div>`).join('')}<div class="field"><label for="reserve-floor">Protected available-cash floor · ${state.currency}</label><input name="floor" id="reserve-floor" type="number" min="0" step=".01" value="${p.cashFloor}" required></div><div class="field"><label for="reserve-source">Opening evidence / assumption</label><input name="source" id="reserve-source" value="${esc(model.source)}" required></div><label class="compare" style="margin-top:20px"><input name="complete" type="checkbox" ${p.partial?'':'checked'}> All eligible bank balances and existing reserves are verified.</label>${model.carryFrom?`<button type="button" class="button" data-reserve-action="refresh-carry" style="margin-top:16px">Refresh projected opening from previous plan</button>`:''}<div class="info-strip">Opening balances are frozen planning assumptions. Carry-forward uses the previous plan’s projected closing bank balances and remaining card reserves; it never reserves those funds twice. This form does not overwrite actual account observations.</div><div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary">Save opening balances</button></div></form>`)};
function reserveCyclesForm(){let p=currentPlan(),rules=reservePolicies(),banks=Object.keys(p.reserveModel.banks);openDrawer('When does a charge become payable?',scopeName()+' · Editable billing-cycle assumptions',`<div class="formula"><b>Charge date → statement cycle → payment due date</b>New charges stay in their expense month. Their payment estimate follows the configured closing day and due date, rather than assuming every charge is payable next month. Confirmed statement dates remain authoritative.</div><form id="reserve-cycles-form">${rules.map((r,i)=>`<div class="drawer-card"><h3>${esc(r.card)}</h3><div class="form-grid"><div class="field"><label for="cycle-close-${i}">Statement closing day</label><input id="cycle-close-${i}" name="close-${i}" type="number" min="1" max="31" value="${r.closeDay}" required></div><div class="field"><label for="cycle-due-${i}">Payment due day</label><input id="cycle-due-${i}" name="due-${i}" type="number" min="1" max="31" value="${r.dueDay}" required></div><div class="field"><label for="cycle-offset-${i}">Due month relative to statement month</label><select id="cycle-offset-${i}" name="offset-${i}">${[0,1,2].map(n=>`<option value="${n}" ${+r.dueOffset===n?'selected':''}>${n===0?'Same month':n===1?'Following month':'Two months later'}</option>`).join('')}</select></div><div class="field"><label for="cycle-bank-${i}">Bank funding new charge earmarks</label><select id="cycle-bank-${i}" name="bank-${i}">${banks.map(name=>`<option ${name===r.bank?'selected':''}>${esc(name)}</option>`).join('')}</select></div></div></div>`).join('')||'<div class="empty">No recorded credit cards in this currency.</div>'}<div class="info-strip">Dates are estimates based on unverified default assumptions until you configure your card. A charge after closing rolls into the following statement. A due date before its statement closing is moved to the next month.</div><div class="form-actions"><button type="button" class="button" data-action="close">Cancel</button><button class="button primary" ${p.status==='closed'?'disabled':''}>Save cycle assumptions</button></div></form>`)}
function reserveExplain(kind){let p=currentPlan(),m=planTotals(p),f=reserveForecast(p),texts={spending:['Monthly consumption',`Directly paid expenses ${money(m.bankSpend)} + card-funded expenses ${money(m.cardSpend)} = ${money(m.spend)}. Card payments ${money(m.card)} are excluded.`],surplus:['Income less consumption',`${money(m.income)} earned income − ${money(m.spend)} consumption = ${money(m.surplus)}. This is different from bank cash flow ${money(m.bankCashflow)}.`],bank:['Bank cash projection',`Opening bank cash ${money(f.start.bank)} + receipts ${money(m.receipts)} − direct expenses ${money(m.bankSpend)} − investments ${money(m.contributions)} − card payments ${money(m.card)} = ${money(f.closing.bank)}. Earmarks do not leave the bank.`],reserves:['Funded card reservations',`Opening card earmarks ${money(f.start.reserved)}. Matching reserve released on payment ${money(sum(f.events,e=>e.released||0))}. Closing funded reserve ${money(f.closing.reserved)}; unfunded requirement ${money(f.shortfall)}. Future reservations are allocated only from available same-account cash.`],available:['Bank cash less reservations',`${money(f.closing.bank)} bank cash − ${money(f.closing.reserved)} funded card reserves − ${money(f.closing.other)} other earmarks = ${money(f.end)} unreserved available. ${f.shortfall?money(f.shortfall)+' of card obligations remain unfunded.':''}`],receipts:['Receipts are not all income',`${money(m.income)} ordinary income + ${money(m.funding)} household funding + ${money(m.reimbursements)} reimbursements + ${money(m.withdrawals)} investment withdrawals = ${money(m.receipts)} cash receipts.`]};let [title,text]=texts[kind];openDrawer(title,monthName()+' · '+scopeName()+' · '+state.currency,`<div class="formula"><b>${title}</b>${text}</div><div class="info-strip">${p.partial?'Partial coverage: unknown bank balances are excluded. ':''}This is a local planning forecast, not a live bank instruction. Monthly consumption, cash payments, and reserves are separate views of linked activity.</div><button class="button" data-plan-tab="calendar" style="margin-top:20px">See daily movements →</button>`)}
function reservePaymentPreview(){let p=currentPlan(),f=reserveForecast(p),payments=f.events.filter(e=>e.type==='cardPayment');openDrawer('A payment uses its earmark',monthName()+' · Projected movements only',`<div class="formula"><b>Available cash change = −payment + released matching reserve</b>A fully earmarked payment reduces bank cash and its reservation by the same amount. Available funds do not fall a second time. A partly funded payment uses additional unreserved cash only for the unfunded portion.</div>${payments.map(e=>`<div class="drawer-card"><h3>${esc(e.title)} · ${e.day} ${plannerMonth(state.month)}</h3><div class="reserve-preview-grid"><span>Bank cash change<b>${money(e.bankDelta)}</b></span><span>Matching earmark released<b>${money(e.released)}</b></span><span>Available cash change<b>${money(e.amount)}</b></span></div><p>Not a new consumption expense. ${e.fundingMismatch?'The reservation is in a different bank account. Review the transfer or funding account before payment.':e.released<e.value?'Only '+money(e.released)+' was earmarked; the remainder needs unreserved bank cash.':'The whole payment is covered by its opening earmark.'}</p></div>`).join('')||'<div class="empty"><h3>No card payment is due this month</h3><p>New card charges build earmarks for their expected payment month.</p></div>'}<button class="button primary" data-reserve-action="fund" style="margin-top:18px">Manage opening earmarks</button>`)}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;let d=b.dataset;if(d.reserveExplain)return reserveExplain(d.reserveExplain);if(d.reserveDay)return reserveDay(d.reserveDay);if(d.reserveAction==='refresh-carry'){let p=currentPlan(),ref=p.reserveModel.carryFrom,prev=ref&&plannerStore.plans[ref.key];if(!prev?.reserveModel)return toast('Previous projection is unavailable.');if(p.status==='closed')return;let f=reserveForecast(prev);p.reserveModel.banks=structuredClone(f.endBanks);p.reserveModel.openingBuckets=structuredClone(f.endBuckets);p.reserveModel.carryFrom.revision=prev.revision;p.opening=f.end;p.partial=true;planRevise('Projected bank balances and carried earmarks refreshed from previous plan');closeDrawer();render();return toast('Projected opening refreshed. Carried funds were not reserved again.')}if(d.reserveAction==='opening')return openingForm();if(d.reserveAction==='fund')return reserveFundingForm();if(d.reserveAction==='cycles')return reserveCyclesForm();if(d.reserveAction==='payment-preview')return reservePaymentPreview();if(d.reserveAction==='autofund'){let p=currentPlan(),left=Object.fromEntries(Object.entries(p.reserveModel.banks).map(([n,b])=>[n,Math.max(0,(b.balance||0)-(b.other||0))]));reserveFundingRows.forEach((t,i)=>{let bank=$('#reserve-bank-'+i).value,n=Math.min(t.required,left[bank]||0);$('#reserve-amount-'+i).value=n;left[bank]-=n})}});
document.addEventListener('submit',e=>{let form=e.target;if(!form.id.startsWith('reserve-'))return;e.preventDefault();let f=new FormData(form),p=currentPlan();if(p.status==='closed')return;if(form.id==='reserve-funding-form'){let next={},byBank={};for(let [i,t]of reserveFundingRows.entries()){let amount=+f.get('amount-'+i),bank=f.get('bank-'+i);if(!Number.isFinite(amount)||amount<0||amount>t.required)return toast('The earmark must be between zero and the obligation amount.');if(amount>0)next[t.key]={key:t.key,card:t.card,statementMonth:t.statementMonth,required:t.required,amount,bank,carried:p.reserveModel.openingBuckets[t.key]?.carried||false};byBank[bank]=(byBank[bank]||0)+amount}for(let [bank,amount]of Object.entries(byBank)){let b=p.reserveModel.banks[bank];if(!b||b.balance===null||amount>b.balance-(b.other||0)+.001)return toast('Not enough known unreserved cash in '+bank+'. Reduce the earmark or verify its opening balance.')}p.reserveModel.openingBuckets=next;planRevise('Opening bank cash earmarked to card obligations; bank balances unchanged');closeDrawer();render();return toast('Earmarks saved. Bank cash unchanged; available cash recalculated.')}if(form.id==='reserve-opening-form'){let next={};for(let [i,[name]]of Object.entries(p.reserveModel.banks).entries()){let val=String(f.get('balance-'+i)),balance=val===''?null:+val,other=+f.get('other-'+i);if(other>(balance||0))return toast('Other earmarks exceed known cash in '+name+'.');let held=sum(Object.values(p.reserveModel.openingBuckets).filter(x=>x.bank===name),x=>x.amount);if(held>Math.max(0,(balance||0)-other))return toast('Reduce the existing card earmarks in '+name+' before lowering this balance.');next[name]={balance,other}}p.reserveModel.banks=next;p.reserveModel.source=String(f.get('source'));p.openingSource=p.reserveModel.source;p.opening=sum(Object.values(next),b=>(b.balance||0)-(b.other||0))-sum(Object.values(p.reserveModel.openingBuckets),b=>b.amount);p.cashFloor=+f.get('floor');p.partial=!f.get('complete')||Object.values(next).some(b=>b.balance===null);p.openingConfirmed=true;planRevise('Gross bank balances and separate earmarks updated');closeDrawer();render();return}if(form.id==='reserve-cycles-form'){reservePolicies().forEach((r,i)=>Object.assign(r,{closeDay:+f.get('close-'+i),dueDay:+f.get('due-'+i),dueOffset:+f.get('offset-'+i),bank:f.get('bank-'+i)}));refreshReserveEstimates();syncAllCardPlans();planRevise('Billing-cycle assumptions and reservation bank updated');closeDrawer();render();return}});
// The existing plan editor's payment-account selection is the card / bank distinction.
const reserveItemEditorBefore=plannerItemForm;plannerItemForm=function(id,lane,preset){reserveItemEditorBefore(id,lane,preset);let field=$('#plan-account');if(field){let hint=document.createElement('p');hint.className='plan-help';hint.textContent='Credit card = consumption now plus a funded cash earmark; bank account = direct cash payment. Configure the card cycle to estimate its later payment date.';field.parentElement.append(hint)}};
const reserveBillEditorBefore=cardBillForm;cardBillForm=function(id){reserveBillEditorBefore(id);let b=scopedBills().find(x=>x.id===id),form=$('#cc-bill-form');if(b&&form){let note=document.createElement('div');note.className='info-strip';note.textContent='Already-paid amounts are opening evidence, not a payment action. If you update prior payment evidence, verify that opening bank balances and carried earmarks already reflect that payment. Use “See payment & release” to inspect the forecast without posting anything.';form.append(note)}};
